import React, { useState } from 'react';
import Button from '@material-ui/core/Button';
import Keycloak from 'keycloak-js';

let initOptions = {
  url: 'http://localhost:8080/',
  realm: 'kcals',
  clientId: 'alsclient',
  onLoad: 'check-sso', // check-sso | login-required
  KeycloakResponseType: 'code',
  //silentCheckSsoRedirectUri: (window.location.origin + "/silent-check-sso.html")
  silentCheckSsoRedirectUri: '/sso'

}

let kc = new Keycloak(initOptions);


kc.init({
  onLoad: initOptions.onLoad,
  KeycloakResponseType: 'code',
  silentCheckSsoRedirectUri: window.location.origin + "/silent-check-sso.html", checkLoginIframe: false,
  pkceMethod: 'S256'
}).then((auth) => {
  console.log('then')
  if(!auth){
      //kc.login()
  }
  else {
    console.info("Authenticated");
    console.log('auth', auth)
    console.log('Keycloak', kc)
    // kc.onTokenExpired = () => {
    //   console.log('token expired')
    //   kc.updateToken(10)
    // }

    localStorage.setItem('auth_token',kc.token)
  }
}, () => {
  console.error("Authenticated Failed");
});


const AlsKc = () => {

  const [infoMessage, setInfoMessage] = useState('');
  if(kc.token){
    localStorage.setItem('auth_token',kc.token)
  }

  return (
    <div className="App">
      {/* <Auth /> */}
      <div className='grid'>
        <div className='col-12'>
          <h1>ApiLogicServer Keycloak Login PoC</h1>
        </div>
      </div>
      
          <Button variant="contained"  onClick={() => { kc.login() }} className='m-1' label='Login' color="primary" >Login</Button>&nbsp;
          <Button variant="contained"  onClick={() => { setInfoMessage(kc.token) }} className="m-1" label='Show Access Token' color="primary" >Show Access Token</Button>&nbsp;
          <Button variant="contained"  onClick={() => { setInfoMessage(JSON.stringify(kc.tokenParsed)) }} className="m-1" label='Show Parsed Access token' color="primary" >Show Parsed Access Token</Button>&nbsp;
          <Button variant="contained"  onClick={() => { setInfoMessage(kc.isTokenExpired(5).toString()) }} className="m-1" label='Check Token expired' color="primary" >Check Token expired</Button>&nbsp;
          <Button variant="contained"  onClick={() => { kc.updateToken(10).then((refreshed)=>{ setInfoMessage('Token Refreshed: ' + refreshed.toString()) }, (e)=>{setInfoMessage('Refresh Error')}) }} 
                                       className="m-1" label='Update Token (if about to expire)' color="primary" >Update Token (if about to expire)</Button>  {/** 10 seconds */}
          <Button variant="contained"  onClick={() => { localStorage.removeItem('auth_token'); kc.logout({ redirectUri: 'https://jsonapi.hardened.be/' }) }} className="m-1" label='Logout'color="primary" >Logout</Button>

            <p style={{ wordBreak: 'break-all' }} id='infoPanel'>
              {infoMessage}
            </p>
          
    <div className="grid">
            <div className="col">
                <Button variant="contained"  onClick={() => { setInfoMessage(kc.token) }} className='m-1' label='Query ApiLogicServer' severity="success" />
            </div>
    </div>

    </div>
  );
}


export default AlsKc;